// Country outlines for the threat map: Natural Earth 1:110m (public domain), via
// world-atlas 2.0.2, in the Natural Earth projection, 1000 units across, latitude
// 84N to 58S. Generated; kept in the source so the map makes no outside requests.

export const MAP_WIDTH = 1000
export const MAP_HEIGHT = 437.7

const LAT_TOP = 84
const LAT_BOTTOM = -58
const X_MAX = 2.735384723480633
const Y_TOP = 1.3823433846208855
const SCALE = 182.78964407016807

/** Where a coordinate falls on the map (Natural Earth projection). */
export function project(lat: number, lon: number): { x: number; y: number } {
  const l = (lon * Math.PI) / 180
  const p = (Math.min(LAT_TOP, Math.max(LAT_BOTTOM, lat)) * Math.PI) / 180
  const p2 = p * p
  const p4 = p2 * p2
  const x = l * (0.8707 - 0.131979 * p2 + p4 * (-0.013791 + p4 * (0.003971 * p2 - 0.001529 * p4)))
  const y = p * (1.007226 + p2 * (0.015085 + p4 * (-0.044475 + 0.028874 * p2 - 0.005916 * p4)))
  return { x: (x + X_MAX) * SCALE, y: (Y_TOP - y) * SCALE }
}

